SELECT id, customerId, deviceNumber, serverPath, originalName, uploadTs, lat, lon, address
FROM plugin_photos_files
WHERE customerId = #{customerId}

    AND deviceNumber = #{deviceNumber}


    AND uploadTs >= #{dateFrom}


    AND uploadTs <= #{dateTo}

ORDER BY uploadTs DESC
LIMIT #{pageSize} OFFSET #{pageNum}

SELECT COUNT(*)
FROM plugin_photos_files
WHERE customerId = #{customerId}

    AND deviceNumber = #{deviceNumber}


    AND uploadTs >= #{dateFrom}


    AND uploadTs <= #{dateTo}
